export function exitCode() {
  return process.exitCode;
}
export function setExitCode(code) {
  process.exitCode = code;
}
export function tryExitCode(code) {
  try {
    process.exitCode = code;
    return "accepted";
  } catch (error) {
    return error.code;
  }
}
export function onExit(log) {
  process.on("exit", (code) => log(`island exit listener ${code} ${process.exitCode}`));
}
